import os
import time
from typing import Optional, Dict, Any

import requests


class AssemblyAITranscriber:
    def __init__(self, api_key: Optional[str] = None, poll_interval: float = 5.0, timeout: float = 3600.0):
        self.api_key = api_key or os.environ.get("ASSEMBLYAI_API_KEY")
        if not self.api_key:
            raise ValueError("Missing AssemblyAI API key. Set ASSEMBLYAI_API_KEY or pass api_key.")
        self.poll_interval = poll_interval
        self.timeout = timeout
        self.base_url = "https://api.assemblyai.com/v2"
        self.headers = {"authorization": self.api_key, "content-type": "application/json"}

    def submit_job(self, audio_url: str, language_code: Optional[str] = None) -> str:
        payload: Dict[str, Any] = {"audio_url": audio_url}
        if language_code:
            payload["language_code"] = language_code

        resp = requests.post(f"{self.base_url}/transcript", headers=self.headers, json=payload, timeout=30)
        resp.raise_for_status()
        data = resp.json()
        transcript_id = data.get("id")
        if not transcript_id:
            raise RuntimeError(f"Unexpected response when creating transcript job: {data}")
        return transcript_id

    def poll_job(self, transcript_id: str) -> Dict[str, Any]:
        deadline = time.time() + self.timeout
        while True:
            resp = requests.get(f"{self.base_url}/transcript/{transcript_id}", headers=self.headers, timeout=30)
            resp.raise_for_status()
            data = resp.json()
            status = data.get("status")

            if status == "completed":
                return data
            if status == "error":
                raise RuntimeError(f"Transcription failed: {data.get('error') or data}")

            if time.time() >= deadline:
                raise TimeoutError(f"Timed out waiting for transcription job {transcript_id}")

            time.sleep(self.poll_interval)

    def transcribe(self, audio_url: str, language_code: Optional[str] = None) -> str:
        transcript_id = self.submit_job(audio_url, language_code=language_code)
        result = self.poll_job(transcript_id)
        transcript = result.get("text")
        if transcript is None:
            raise RuntimeError(f"Completed job missing transcript text: {result}")
        return transcript


def poll_transcription_job_and_return_transcript(audio_url: str, api_key: Optional[str] = None) -> str:
    return AssemblyAITranscriber(api_key=api_key).transcribe(audio_url)
